using System;using System.IO;using System.Linq;
class DiscoveryTests{static void Main(){var root=AppDomain.CurrentDomain.BaseDirectory;AppStore.TestDirectory=Path.Combine(Path.GetTempPath(),"CorePilot-discovery-"+Guid.NewGuid().ToString("N"));var result=CcdDiscovery.Scan(Native.Topology());Console.WriteLine(result.Brand);Console.WriteLine(result.Model);Console.WriteLine(result.Ready+" "+result.Reason);foreach(var g in result.Groups)Console.WriteLine("CCD"+g.Number+" keys="+string.Join(",",g.Cores)+" L3="+g.L3Bytes);if(result.Brand.IndexOf("AMD",StringComparison.OrdinalIgnoreCase)<0)throw new Exception("Expected AMD CPU on this machine");if(!result.Ready)throw new Exception("Current machine cross-check failed: "+result.Reason);if(result.Groups.Count<2||result.Groups.SelectMany(g=>g.Cores).Distinct().Count()!=Native.Topology().Count)throw new Exception("CCD map is incomplete or overlaps");Console.WriteLine("PASS current machine CPUID + Windows cache/core/CPU-set cross-check");}}

